    test('XdrPathPaymentStrictSendResult success arm round trip', () {
      var original = XdrPathPaymentStrictSendResult(
        XdrPathPaymentStrictSendResultCode.PATH_PAYMENT_STRICT_SEND_SUCCESS,
      );
      original.success = (XdrPathPaymentResultSuccess(
        [],
        XdrSimplePaymentResult(
          (XdrMuxedAccount(XdrCryptoKeyType.KEY_TYPE_ED25519)
            ..ed25519 = XdrUint256(
              Uint8List.fromList(List<int>.filled(32, 0xAB)),
            )),
          XdrAsset(XdrAssetType.ASSET_TYPE_NATIVE),
          XdrInt64(BigInt.from(1000)),
        ),
      ));
      expect(
        (original.toXdrJsonValue() as Map<String, Object?>).keys.single,
        'success',
      );
      var json = original.toXdrJson();
      var fromDocument = XdrPathPaymentStrictSendResult.fromXdrJson(json);
      expect(fromDocument.toXdrJson(), json);
      expect(
        fromDocument.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
      var fromTree = XdrPathPaymentStrictSendResult.fromXdrJsonValue(
        original.toXdrJsonValue(),
      );
      expect(fromTree.toXdrJsonValue(), original.toXdrJsonValue());
      expect(
        fromTree.toBase64EncodedXdrString(),
        original.toBase64EncodedXdrString(),
      );
    });
